package io.xeros.content.commands.all;
import io.xeros.content.commands.Command;import io.xeros.model.entity.player.Player;import io.xeros.content.combat.magic.SoloEquipmentCharges;
public class Charge extends Command{public void execute(Player p,String name,String input){if(!Boolean.getBoolean("solo.mode"))return;String[] args=input.trim().toLowerCase().split(" +");try{int id=args[0].equals("shadow")?27275:args[0].equals("scythe")?22325:args[0].equals("bowfa")?25865:Integer.parseInt(args[0]);if(args.length>1&&args[1].equals("max")){if(id!=27275){p.sendMessage("Use ::charge shadow max para a Tumeken's shadow (27275).");return;}String key=p.getEquipmentChargeLedger().choose(27275,-1);if(key==null){p.sendMessage("Tenha Tumeken's shadow (27275) equipada ou na mochila.");return;}p.getEquipmentChargeLedger().set(key,20000);p.sendMessage("Shadow carregada com 20.000 cargas, sem consumir materiais.");SoloEquipmentCharges.check(p);return;}int slot=args.length>1?Integer.parseInt(args[1])-1:-1;if(slot< -1||slot>=28)throw new NumberFormatException();SoloEquipmentCharges.charge(p,id,slot);}catch(NumberFormatException e){p.sendMessage("Use ::charge shadow / scythe / bowfa / ID [posicao 1 a 28], com materiais.");}}}
